-- Kolom boss_sprite: sprite boss per course (orc/lich/dragon).
-- Course baru tinggal pakai ulang salah satunya.
alter table public.courses add column if not exists boss_sprite text;

insert into public.courses (id, title, tagline, icon, boss_icon, boss_name, boss_sprite, color, sort_order) values ($qa$jarkom$qa$, $qa$Jaringan Komputer$qa$, $qa$Kuasai paket data dari kabel sampai cloud.$qa$, $qa$🌐$qa$, $qa$👾$qa$, $qa$ORC CHAMPION$qa$, $qa$orc$qa$, $qa$cyan$qa$, 1) on conflict (id) do update set title = excluded.title, tagline = excluded.tagline, icon = excluded.icon, boss_icon = excluded.boss_icon, boss_name = excluded.boss_name, boss_sprite = excluded.boss_sprite, color = excluded.color, sort_order = excluded.sort_order;
insert into public.courses (id, title, tagline, icon, boss_icon, boss_name, boss_sprite, color, sort_order) values ($qa$ib$qa$, $qa$Inteligensi Buatan$qa$, $qa$Dari agen cerdas sampai planning.$qa$, $qa$🧠$qa$, $qa$🤖$qa$, $qa$LICH KING$qa$, $qa$lich$qa$, $qa$magenta$qa$, 2) on conflict (id) do update set title = excluded.title, tagline = excluded.tagline, icon = excluded.icon, boss_icon = excluded.boss_icon, boss_name = excluded.boss_name, boss_sprite = excluded.boss_sprite, color = excluded.color, sort_order = excluded.sort_order;
insert into public.courses (id, title, tagline, icon, boss_icon, boss_name, boss_sprite, color, sort_order) values ($qa$pemweb$qa$, $qa$Pemrograman Web$qa$, $qa$Dari HTML sampai React.$qa$, $qa$💻$qa$, $qa$🕷️$qa$, $qa$BLACK DRAGON$qa$, $qa$dragon$qa$, $qa$orange$qa$, 3) on conflict (id) do update set title = excluded.title, tagline = excluded.tagline, icon = excluded.icon, boss_icon = excluded.boss_icon, boss_name = excluded.boss_name, boss_sprite = excluded.boss_sprite, color = excluded.color, sort_order = excluded.sort_order;
